cat > "$FAKE_IROHA_ROOT/target/debug/iroha" <<'EOF'
#!/bin/sh
if [ -n "${SORASWAP_IROHA_DEV_ARGS_PATH:-}" ]; then
  printf '%s\n' "$@" > "$SORASWAP_IROHA_DEV_ARGS_PATH"
fi
if [ -n "${SORASWAP_IROHA_DEV_PWD_PATH:-}" ]; then
  pwd > "$SORASWAP_IROHA_DEV_PWD_PATH"
fi
case " $* " in
  *" contract dev check "*)
    manifest="iroha.contracts.toml"
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --manifest)
          manifest="$2"
          shift 2
          ;;
        --manifest=*)
          manifest="${1#--manifest=}"
          shift
          ;;
        *)
          shift
          ;;
      esac
    done
    python3 - "$manifest" <<'PY'
import json
import sys
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:
    import tomli as tomllib

manifest = Path(sys.argv[1]).resolve()
root = manifest.parent
data = tomllib.loads(manifest.read_text())
for contract in data.get("contracts", []):
    source = contract.get("source")
    if source and not (root / source).is_file():
        print(f"failed to canonicalize `{root / source}`: No such file or directory", file=sys.stderr)
        raise SystemExit(1)
print(json.dumps({"ok": True}, sort_keys=True))
PY
    exit $?
    ;;
  *" contract dev test "*)
    manifest="iroha.contracts.toml"
    test_calls="${SORASWAP_KOTO_TEST_CALLS:-/dev/null}"
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --manifest)
          manifest="$2"
          shift 2
          ;;
        --manifest=*)
          manifest="${1#--manifest=}"
          shift
          ;;
        *)
          shift
          ;;
      esac
    done
    python3 - "$manifest" "$test_calls" <<'PY'
import sys
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:
    import tomli as tomllib

manifest = Path(sys.argv[1]).resolve()
output = Path(sys.argv[2])
data = tomllib.loads(manifest.read_text())
with output.open("a", encoding="utf-8") as stream:
    for index, test in enumerate(data.get("tests", [])):
        path = test.get("path")
        if not isinstance(path, str):
            print(f"`tests[{index}].path` must be a string", file=sys.stderr)
            raise SystemExit(1)
        resolved = manifest.parent / path
        if not resolved.is_file():
            print(
                f"Kotodama tests in `{resolved}` failed: failed to read {resolved}: "
                "No such file or directory",
                file=sys.stderr,
            )
            raise SystemExit(1)
        stream.write(f"{resolved.resolve()}\n")
PY
    exit $?
    ;;
  *" contract dev schema "*)
    manifest="iroha.contracts.toml"
    out="docs/contracts.md"
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --manifest)
          manifest="$2"
          shift 2
          ;;
        --manifest=*)
          manifest="${1#--manifest=}"
          shift
          ;;
        --out)
          out="$2"
          shift 2
          ;;
        --out=*)
          out="${1#--out=}"
          shift
          ;;
        *)
          shift
          ;;
      esac
    done
    python3 - "$manifest" "$out" <<'PY'
import json
import sys
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:
    import tomli as tomllib

manifest = Path(sys.argv[1]).resolve()
root = manifest.parent
data = tomllib.loads(manifest.read_text())
sections = []
for contract in data.get("contracts", []):
    name = contract.get("name", "unknown")
    artifact = contract.get("artifact")
    if not artifact:
        continue
    interface = (root / artifact).with_suffix(".interface.json")
    if not interface.is_file():
        print(
            f"missing interface JSON for {name}: "
            f"{interface.relative_to(root)}; run make compile first",
            file=sys.stderr,
        )
        raise SystemExit(1)
    schema = json.loads(interface.read_text())
    lines = [f"## {name}", ""]
    lines.extend(
        f"- `{entrypoint.get('name', 'unknown')}`"
        for entrypoint in schema.get("entrypoints", [])
    )
    sections.append("\n".join(lines))

output = root / sys.argv[2]
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text("\n\n".join(sections) + "\n", encoding="utf-8")
PY
    exit $?
    ;;
  *" contract dev build "*)
    manifest="iroha.contracts.toml"
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --manifest)
          manifest="$2"
          shift 2
          ;;
        --manifest=*)
          manifest="${1#--manifest=}"
          shift
          ;;
        *)
          shift
          ;;
      esac
    done
    python3 - "$manifest" <<'PY'
import json
import sys
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:
    import tomli as tomllib

manifest = Path(sys.argv[1]).resolve()
root = manifest.parent
data = tomllib.loads(manifest.read_text())
contracts = []
for contract in data.get("contracts", []):
    artifact = contract.get("artifact")
    if not artifact:
        continue
    artifact_path = root / artifact
    artifact_path.parent.mkdir(parents=True, exist_ok=True)
    stem = artifact_path.with_suffix("")
    artifact_path.write_text("compiled by fake iroha" + chr(10), encoding="utf-8")
    Path(str(stem) + ".manifest.json").write_text(
        json.dumps({"entrypoints": [], "states": []}) + chr(10),
        encoding="utf-8",
    )
    Path(str(stem) + ".interface.json").write_text(
        json.dumps({"entrypoints": [], "states": []}) + chr(10),
        encoding="utf-8",
    )
    Path(str(stem) + ".source-map.json").write_text("{}" + chr(10), encoding="utf-8")
    Path(str(stem) + ".budget.json").write_text("[]" + chr(10), encoding="utf-8")
    contracts.append(contract.get("name", "unknown"))
print(json.dumps({"ok": True, "contracts": contracts}, sort_keys=True))
PY
    exit $?
    ;;
  *" contract manifest build "*)
    printf '%s\n' 'fake iroha: manifest build stderr noise' >&2
    cat <<'JSON'
{"code_hash":"hash:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA#CAFE","abi_hash":"hash:BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB#BEEF","entrypoints":[{"name":"canonical_manifest_entrypoint"}],"state":{"keys":["fixture"]}}
JSON
    exit 0
    ;;
  *" ledger account get "*)
    exit 1
    ;;
esac

network_prefix=""
last=""
while [ "$#" -gt 0 ]; do
  case "$1" in
    --network-prefix)
      network_prefix="$2"
      shift 2
      ;;
    *)
      last="$1"
      shift
      ;;
  esac
done
printf 'acct:%s:%s\n' "$network_prefix" "$last"
EOF

