python3 - "$ROOT" <<'PY'
import sys
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:
    import tomli as tomllib

root = Path(sys.argv[1])
manifest_path = root / "iroha.contracts.toml"
contract_manifest_paths = sorted(root.rglob("iroha.contracts.toml"))
legacy_manifest_paths = sorted(root.rglob("iroha.app.toml"))
if contract_manifest_paths != [manifest_path] or legacy_manifest_paths:
    raise SystemExit(
        "contract manifest drift: "
        f"iroha_contracts_manifests={contract_manifest_paths} "
        f"retired_iroha_app_manifests={legacy_manifest_paths}"
    )
manifest = tomllib.loads(manifest_path.read_text())
manifest_contract_source_paths = [
    str(root / contract["source"])
    for contract in manifest.get("contracts", [])
    if contract.get("source")
]
manifest_contract_sources = set(manifest_contract_source_paths)
contract_names = [
    contract["name"]
    for contract in manifest.get("contracts", [])
    if contract.get("name")
]
contract_aliases = [
    contract["alias"]
    for contract in manifest.get("contracts", [])
    if contract.get("alias")
]
contract_artifacts = [
    contract["artifact"]
    for contract in manifest.get("contracts", [])
    if contract.get("artifact")
]
expected_generated_interfaces = {
    f'./{Path(contract["artifact"]).with_suffix(".interface.json")}'
    for contract in manifest.get("contracts", [])
    if contract.get("artifact")
}
repo_contract_sources = {
    str(path)
    for path in (root / "contracts").glob("**/*.ko")
}
repo_contract_modules = {
    path.relative_to(root).parts[1]
    for path in (root / "contracts").glob("**/*.ko")
}
doc_name_for_module = {
    "escrow": "conditional_escrow",
    "n3x": "n3x_hub",
    "rwa": "rwa_market",
}
expected_module_docs = {
    doc_name_for_module.get(module, module)
    for module in repo_contract_modules
}
interface_docs = {
    path.stem
    for path in (root / "docs" / "interface_specs").glob("*.md")
    if path.name not in {"README.md", "generated.md"}
}
state_docs = {
    path.stem
    for path in (root / "docs" / "state_layouts").glob("*.md")
    if path.name != "README.md"
}
generated_doc = root / "docs" / "interface_specs" / "generated.md"
if generated_doc.is_file():
    generated_lines = generated_doc.read_text().splitlines()
    generated_contracts = {
        line.removeprefix("## ")
        for line in generated_lines
        if line.startswith("## ")
    }
    generated_interfaces = {
        line.split("`", 2)[1]
        for line in generated_lines
        if line.startswith("- Interface: `") and "`" in line
    }
else:
    generated_contracts = set()
    generated_interfaces = set()
manifest_test_paths = [
    str(root / test["path"])
    for test in manifest.get("tests", [])
    if test.get("path")
]
manifest_tests = set(manifest_test_paths)
repo_tests = {
    str(path)
    for path in (root / "tests" / "kotodama").glob("*.ko")
}
dedicated_tests = set()
dedicated_docs = set()
smoke_ids = [
    smoke["id"]
    for smoke in manifest.get("smoke", [])
    if smoke.get("id")
]
smoke_contracts = {
    smoke["contract"]
    for smoke in manifest.get("smoke", [])
    if smoke.get("contract")
}

def duplicates(values):
    seen = set()
    dupes = set()
    for value in values:
        if value in seen:
            dupes.add(value)
        seen.add(value)
    return sorted(dupes)

missing_contracts = sorted(repo_contract_sources - manifest_contract_sources)
stale_contracts = sorted(manifest_contract_sources - repo_contract_sources)
missing_tests = sorted(repo_tests - manifest_tests - dedicated_tests)
stale_tests = sorted(manifest_tests - repo_tests)
missing_interface_docs = sorted(expected_module_docs - interface_docs)
stale_interface_docs = sorted(interface_docs - expected_module_docs - dedicated_docs)
missing_state_docs = sorted(expected_module_docs - state_docs)
stale_state_docs = sorted(state_docs - expected_module_docs - dedicated_docs)
missing_generated_contracts = sorted(set(contract_names) - generated_contracts)
stale_generated_contracts = sorted(generated_contracts - set(contract_names))
missing_generated_interfaces = sorted(expected_generated_interfaces - generated_interfaces)
stale_generated_interfaces = sorted(generated_interfaces - expected_generated_interfaces)
duplicate_contracts = duplicates(contract_names)
duplicate_contract_aliases = duplicates(contract_aliases)
duplicate_contract_sources = duplicates(manifest_contract_source_paths)
duplicate_artifacts = duplicates(contract_artifacts)
duplicate_tests = duplicates(manifest_test_paths)
duplicate_smoke_ids = duplicates(smoke_ids)
unknown_smoke_contracts = sorted(smoke_contracts - set(contract_names))
non_universal_contract_aliases = sorted(
    alias for alias in contract_aliases if not alias.endswith(".universal")
)
if (
    missing_contracts
    or stale_contracts
    or missing_tests
    or stale_tests
    or missing_interface_docs
    or stale_interface_docs
    or missing_state_docs
    or stale_state_docs
    or missing_generated_contracts
    or stale_generated_contracts
    or missing_generated_interfaces
    or stale_generated_interfaces
    or duplicate_contracts
    or duplicate_contract_aliases
    or duplicate_contract_sources
    or duplicate_artifacts
    or duplicate_tests
    or duplicate_smoke_ids
    or unknown_smoke_contracts
    or non_universal_contract_aliases
):
    raise SystemExit(
        "iroha.contracts.toml drift: "
        f"missing_contracts={missing_contracts} "
        f"stale_contracts={stale_contracts} "
        f"missing_tests={missing_tests} "
        f"stale_tests={stale_tests} "
        f"missing_interface_docs={missing_interface_docs} "
        f"stale_interface_docs={stale_interface_docs} "
        f"missing_state_docs={missing_state_docs} "
        f"stale_state_docs={stale_state_docs} "
        f"missing_generated_contracts={missing_generated_contracts} "
        f"stale_generated_contracts={stale_generated_contracts} "
        f"missing_generated_interfaces={missing_generated_interfaces} "
        f"stale_generated_interfaces={stale_generated_interfaces} "
        f"duplicate_contracts={duplicate_contracts} "
        f"duplicate_contract_aliases={duplicate_contract_aliases} "
        f"duplicate_contract_sources={duplicate_contract_sources} "
        f"duplicate_artifacts={duplicate_artifacts} "
        f"duplicate_tests={duplicate_tests} "
        f"duplicate_smoke_ids={duplicate_smoke_ids} "
        f"unknown_smoke_contracts={unknown_smoke_contracts} "
        f"non_universal_contract_aliases={non_universal_contract_aliases}"
    )
PY

