import re
import sys
from pathlib import Path

taira_path = Path(sys.argv[1])
production_path = Path(sys.argv[2])

target_map = {
    "taira-preflight": "production-preflight",
    "testnet-nested-call-probe": "production-nested-call-probe",
    "record-testnet-rwa-compliance": "record-production-rwa-compliance",
    "deploy-testnet": "deploy-production",
    "smoke-testnet-readonly": "smoke-production-readonly",
    "smoke-testnet": "smoke-production",
    "test-contract-console-testnet": "test-contract-console-production",
    "smoke-testnet-trader-readonly": "smoke-production-trader-readonly",
    "smoke-testnet-trader": "smoke-production-trader",
    "publish-trader-api": "publish-production-trader-api",
    "release-checklist": "release-production-checklist",
}

def release_script_shape(path):
    text = path.read_text()
    total_match = re.search(r"release_phase_total=(\d+)", text)
    if not total_match:
        raise SystemExit(f"{path.name} does not declare release_phase_total")
    targets = re.findall(
        r"^(?:(?:[A-Z0-9_]+=\S+)\s+)*run_target\s+([a-z0-9-]+)",
        text,
        flags=re.MULTILINE,
    )
    return int(total_match.group(1)), targets

taira_total, taira_targets = release_script_shape(taira_path)
production_total, production_targets = release_script_shape(production_path)
if taira_total != len(taira_targets):
    raise SystemExit(
        f"{taira_path.name} release_phase_total={taira_total} but has "
        f"{len(taira_targets)} run_target calls"
    )
if production_total != len(production_targets):
    raise SystemExit(
        f"{production_path.name} release_phase_total={production_total} but has "
        f"{len(production_targets)} run_target calls"
    )

expected_production_targets = [target_map[target] for target in taira_targets]
if production_targets != expected_production_targets:
    raise SystemExit(
        "production release phase drift: "
        f"expected={expected_production_targets} actual={production_targets}"
    )
PY
