python3 - "$ROOT/Makefile" "$ROOT/README.md" <<'PY'
import re
import sys
from pathlib import Path

makefile = Path(sys.argv[1]).read_text()
readme = Path(sys.argv[2]).read_text()
phony_targets = set()
for line in makefile.splitlines():
    if line.startswith(".PHONY:"):
        phony_targets.update(line.split(":", 1)[1].split())

try:
    command_block = readme.split("## Commands", 1)[1].split("```bash", 1)[1].split("```", 1)[0]
except IndexError as exc:
    raise SystemExit("README has no bash command block under ## Commands") from exc

documented_targets = set()
for line in command_block.splitlines():
    match = re.search(r"\bmake\s+([a-z0-9:-]+)", line)
    if match:
        documented_targets.add(match.group(1))

missing = sorted(phony_targets - documented_targets)
unknown = sorted(documented_targets - phony_targets)
if missing or unknown:
    raise SystemExit(
        "README command block drift: "
        f"missing_from_readme={missing} unknown_in_readme={unknown}"
    )
PY
