#!/bin/sh
fail_release_env() {
  echo "fake make saw release env leak: $*" >&2
  exit 77
}

target=""
for target do :; done
[ -n "$target" ] || fail_release_env "missing target"

candidate_pin_enabled=0
if [ -n "${PIN_FIXTURE_ROOT:-}" ] || [ -n "${PIN_FIXTURE_BUNDLE:-}" ]; then
  [ -n "${PIN_FIXTURE_ROOT:-}" ] && [ -n "${PIN_FIXTURE_BUNDLE:-}" ] \
    || fail_release_env "partial candidate pin fixture"
  candidate_pin_enabled=1
fi

pin_target_policy="ordinary"
case "$target" in
  lint|compile|dev-check|dev-build|dev-test|dev-schema|test-local-foundation-isolated|test-local-isolated)
    pin_target_policy="candidate"
    if [ "$candidate_pin_enabled" -eq 1 ]; then
      [ "${SORASWAP_IROHA_ROOT:-}" = "$PIN_FIXTURE_ROOT" ] \
        || fail_release_env "$target candidate root"
      [ "${SORASWAP_IROHA_CLI_BIN:-}" = "$PIN_FIXTURE_BUNDLE/bin/iroha" ] \
        || fail_release_env "$target candidate cli"
      [ "${SORASWAP_SKIP_IROHA_CLI_BUILD:-}" = "1" ] \
        || fail_release_env "$target cli build skip"
    else
      [ -z "${SORASWAP_IROHA_ROOT:-}" ] \
        || fail_release_env "$target unexpected candidate root"
      [ -z "${SORASWAP_IROHA_CLI_BIN:-}" ] \
        || fail_release_env "$target unexpected candidate cli"
      [ -z "${SORASWAP_SKIP_IROHA_CLI_BUILD:-}" ] \
        || fail_release_env "$target unexpected cli build skip"
    fi
    ;;
  *)
    [ -z "${SORASWAP_IROHA_ROOT:-}" ] \
      || fail_release_env "$target unexpected candidate root"
    [ -z "${SORASWAP_IROHA_CLI_BIN:-}" ] \
      || fail_release_env "$target unexpected candidate cli"
    [ -z "${SORASWAP_SKIP_IROHA_CLI_BUILD:-}" ] \
      || fail_release_env "$target unexpected cli build skip"
    ;;
esac

case "$target" in
  test-local-foundation-isolated|test-local-isolated)
    pin_target_policy="isolated"
    if [ "$candidate_pin_enabled" -eq 1 ]; then
      [ "${IROHA3D_BIN:-}" = "$PIN_FIXTURE_BUNDLE/bin/iroha3d" ] \
        || fail_release_env "$target iroha3d"
