        || fail_release_env "$target iroha"
      [ "${KAGAMI_BIN:-}" = "$PIN_FIXTURE_ROOT/target/release/kagami" ] \
        || fail_release_env "$target kagami"
      [ "${SORASWAP_SKIP_LOCALNET_TOOL_BUILD:-}" = "1" ] \
        || fail_release_env "$target localnet build skip"
      [ "${SORASWAP_ISOLATED_LOCAL_UP_TIMEOUT_SECS:-}" = "0" ] \
        || fail_release_env "$target local-up timeout"
      [ "${SORASWAP_ISOLATED_DEPLOY_TIMEOUT_SECS:-}" = "0" ] \
        || fail_release_env "$target deploy timeout"
      [ "${SORASWAP_ISOLATED_SMOKE_TIMEOUT_SECS:-}" = "0" ] \
        || fail_release_env "$target smoke timeout"
      [ "${SORASWAP_ISOLATED_TESTNET_SMOKE_TIMEOUT_SECS:-}" = "0" ] \
        || fail_release_env "$target testnet smoke timeout"
    else
      [ -z "${IROHA3D_BIN:-}" ] || fail_release_env "$target unexpected iroha3d"
      [ -z "${IROHA_BIN:-}" ] || fail_release_env "$target unexpected iroha"
      [ -z "${KAGAMI_BIN:-}" ] || fail_release_env "$target unexpected kagami"
      [ -z "${SORASWAP_SKIP_LOCALNET_TOOL_BUILD:-}" ] \
        || fail_release_env "$target unexpected localnet build skip"
      [ -z "${SORASWAP_ISOLATED_LOCAL_UP_TIMEOUT_SECS:-}" ] \
        || fail_release_env "$target unexpected local-up timeout"
      [ -z "${SORASWAP_ISOLATED_DEPLOY_TIMEOUT_SECS:-}" ] \
        || fail_release_env "$target unexpected deploy timeout"
      [ -z "${SORASWAP_ISOLATED_SMOKE_TIMEOUT_SECS:-}" ] \
        || fail_release_env "$target unexpected smoke timeout"
      [ -z "${SORASWAP_ISOLATED_TESTNET_SMOKE_TIMEOUT_SECS:-}" ] \
        || fail_release_env "$target unexpected testnet smoke timeout"
    fi
    ;;
  *)
    [ -z "${IROHA3D_BIN:-}" ] || fail_release_env "$target unexpected iroha3d"
    [ -z "${IROHA_BIN:-}" ] || fail_release_env "$target unexpected iroha"
    [ -z "${KAGAMI_BIN:-}" ] || fail_release_env "$target unexpected kagami"
