    [ -z "${SORASWAP_ISOLATED_LOCAL_UP_TIMEOUT_SECS:-}" ] \
      || fail_release_env "$target unexpected local-up timeout"
    [ -z "${SORASWAP_ISOLATED_DEPLOY_TIMEOUT_SECS:-}" ] \
      || fail_release_env "$target unexpected deploy timeout"
    [ -z "${SORASWAP_ISOLATED_SMOKE_TIMEOUT_SECS:-}" ] \
      || fail_release_env "$target unexpected smoke timeout"
    [ -z "${SORASWAP_ISOLATED_TESTNET_SMOKE_TIMEOUT_SECS:-}" ] \
      || fail_release_env "$target unexpected testnet smoke timeout"
    ;;
esac

