	        export "$release_env_leak_name=$FAKE_IROHA_ROOT"
	        ;;
		      *)
		        export "$release_env_leak_name=leaky"
	        ;;
    esac
  done
  export SORASWAP_UNLISTED_RELEASE_LOCAL_ACCEPTANCE_LEAK=leaky
  export IROHA_UNLISTED_RELEASE_LOCAL_ACCEPTANCE_LEAK=leaky
  export KAGAMI_UNLISTED_RELEASE_LOCAL_ACCEPTANCE_LEAK=leaky
  export MAKEFLAGS=-n
  export MFLAGS=-n
  export GNUMAKEFLAGS=-n
  export MAKEFILES="$TMP_DIR/extra-release-checklist.mk"
  export MAKEOVERRIDES="DRY_RUN=1"
  export PATH="$fake_make_dir:$PATH"
  run_release_checklist
) >"$checklist_positive_output" 2>&1
