rg -q "release checklist: make simulate-full" "$checklist_positive_output"
rg -q "release checklist ok" "$checklist_positive_output"

make_closeout_pin_fixture() {
  local destination="$1"
  local pin_dir="$destination.closeout-pin"
  local iroha_root="$pin_dir/iroha"
  local git_sha bundle_name bundle

  mkdir -p \
    "$iroha_root/crates/iroha_kagami/src" \
    "$iroha_root/crates/iroha_swarm/src" \
    "$iroha_root/crates/iroha_test_samples/src"
  cat > "$iroha_root/.gitignore" <<'EOF'
/target/
EOF
  cat > "$iroha_root/Cargo.toml" <<'EOF'
[workspace]
members = []
EOF
  printf '%s\n' '# fixture lock' > "$iroha_root/Cargo.lock"
  printf '%s\n' '// kagami fixture' > "$iroha_root/crates/iroha_kagami/src/lib.rs"
  printf '%s\n' '// swarm fixture' > "$iroha_root/crates/iroha_swarm/src/lib.rs"
  printf '%s\n' '// samples fixture' > "$iroha_root/crates/iroha_test_samples/src/lib.rs"
  git -C "$iroha_root" init -q
  git -C "$iroha_root" config user.name "SoraSwap Closeout Pin"
  git -C "$iroha_root" config user.email "closeout-pin@example.invalid"
  configure_fixture_ssh_signing "$iroha_root" "$pin_dir/signing" "closeout-pin@example.invalid"
  git -C "$iroha_root" add .
  git -C "$iroha_root" commit -S -q -m "closeout pin fixture"
  git_sha="$(git -C "$iroha_root" rev-parse HEAD)"
  printf '%s\n' "$git_sha" > "$pin_dir/expected.sha"
  mkdir -p "$iroha_root/target/release"
  cat > "$iroha_root/target/release/kagami" <<'EOF'
#!/bin/sh
exit 0
EOF
  chmod +x "$iroha_root/target/release/kagami"
  touch "$iroha_root/target/release/kagami"

  bundle_name="taira-rollout-${git_sha[1,12]}-release"
  bundle="$pin_dir/bundle/$bundle_name"
  mkdir -p "$bundle/bin"
  for binary_name in iroha3d iroha; do
    printf '#!/bin/sh\n# Iroha Git SHA: %s\nexit 0\n' "$git_sha" > "$bundle/bin/$binary_name"
    chmod +x "$bundle/bin/$binary_name"
  done
  jq -n \
    --arg git_head "$git_sha" \
    --arg bundle_name "$bundle_name" \
    '{
      git_head: $git_head,
      git_signature_verified: true,
      git_tree_clean: true,
      git_status_lines: [],
      cargo_profile: "release",
      bundle_name: $bundle_name,
      iroha3d_features: ["embedded-soracloud-runtime", "sccp-test-fixtures"],
      binaries: ["bin/iroha3d", "bin/iroha"],
      prebundle_checks: [
        {name: "soraswap_smart_contract_deploy_router_regression", skipped: false},
        {name: "soraswap_three_hop_nested_transfer_canary", skipped: false}
      ]
    }' > "$bundle/rollout.manifest.json"
  (
    cd "$bundle"
    shasum -a 256 bin/iroha bin/iroha3d rollout.manifest.json > sha256sums.txt
  )
  COPYFILE_DISABLE=1 tar -C "${bundle:h}" -czf "${bundle}.tar.gz" "${bundle:t}"
  printf '%s  %s\n' "$(shasum -a 256 "${bundle}.tar.gz" | awk '{print $1}')" "${bundle:t}.tar.gz" \
    > "${bundle}.tar.gz.sha256"
}

make_closeout_fixture() {
  local destination="$1"

  cp -R "$checklist_contract_fixture_root" "$destination"
  mkdir -p "$destination/scripts" "$destination/tests"
  cat > "$destination/.gitignore" <<'EOF'
/artifacts/
/deployments/
/tmp*
EOF
  cat > "$destination/scripts/check_shell_syntax.sh" <<'EOF'
#!/bin/zsh
set -euo pipefail
root="${SORASWAP_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
[[ ! -f "$root/tmp/force-check-shell-failure" ]] || exit 41
exit 0
EOF
  cat > "$destination/scripts/redact_generated_evidence.sh" <<'EOF'
#!/bin/zsh
set -euo pipefail
root="${SORASWAP_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
[[ ! -f "$root/tmp/force-redaction-failure" ]] || exit 42
exit 0
EOF
  cat > "$destination/tests/public_env_helper_smoke.sh" <<'EOF'
#!/bin/zsh
set -euo pipefail
exit 0
EOF
  chmod +x \
    "$destination/scripts/check_shell_syntax.sh" \
    "$destination/scripts/redact_generated_evidence.sh" \
    "$destination/tests/public_env_helper_smoke.sh"
  git -C "$destination" init -q
  git -C "$destination" config user.name "SoraSwap Closeout Fixture"
  git -C "$destination" config user.email "soraswap-closeout@example.invalid"
  configure_fixture_ssh_signing "$destination" "$destination.closeout-signing" "soraswap-closeout@example.invalid"
  git -C "$destination" add .gitignore contracts docs scripts tests
  git -C "$destination" commit -S -q -m "closeout fixture"
  make_closeout_pin_fixture "$destination"
}

prepare_closeout_fixture() {
  local destination="$1"
  local output="$2"
  local token journal phase_index pin_git_sha pin_root pin_bundle pin_make_log
  typeset -a phase_targets

  make_closeout_fixture "$destination"
  pin_root="$(cd "$destination.closeout-pin/iroha" && pwd -P)"
  pin_git_sha="$(<"$destination.closeout-pin/expected.sha")"
  pin_bundle="$(
    cd "$destination.closeout-pin/bundle/taira-rollout-${pin_git_sha[1,12]}-release" \
      && pwd -P
  )"
  pin_make_log="${output%.out}.pin-targets.log"
  : > "$pin_make_log"
  journal="$destination/tmp/release-closeout/testnet.phase-journal.json"
  phase_targets=("${(@f)$(release_closeout_expected_phase_targets testnet)}")
  export SORASWAP_RELEASE_EXPECTED_GIT_SHA="$(git -C "$destination" rev-parse HEAD)"
  token="$(release_phase_journal_state create "$destination" testnet "$journal" "${phase_targets[@]}")"
  release_phase_journal_state record "$destination" testnet "$journal" 1 "${phase_targets[1]}" \
    "$destination/deployments/testnet/preflight.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 2 "${phase_targets[2]}" \
    "$destination/deployments/testnet/chain.latest.json" \
    "$destination/deployments/testnet/nested_call_probe.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 3 "${phase_targets[3]}" \
    "$destination/deployments/testnet/preflight.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 4 "${phase_targets[4]}" \
    "$destination/deployments/testnet/rwa_compliance.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 5 "${phase_targets[5]}" \
    "$destination/deployments/testnet/deploy.latest.json" \
    "$destination/deployments/testnet/contracts.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 6 "${phase_targets[6]}" \
    "$destination/deployments/testnet/smoke.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 7 "${phase_targets[7]}" \
    "$destination/deployments/testnet/smoke.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 8 "${phase_targets[8]}" \
    "$destination/deployments/testnet/contract_console_smoke.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 9 "${phase_targets[9]}" \
    "$destination/deployments/testnet/trader_readonly.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 10 "${phase_targets[10]}" \
    "$destination/deployments/testnet/trader.latest.json"
  release_phase_journal_state record "$destination" testnet "$journal" 11 "${phase_targets[11]}" \
    "$destination/deployments/testnet/trader_api_bundle.latest.json"
  (
    export SORASWAP_ROOT="$destination"
    export SORASWAP_RELEASE_ENV=testnet
    export RELEASE_CHECKLIST_INTERNAL_CLOSEOUT_TOKEN="$token"
    export RELEASE_CHECKLIST_INTERNAL_CLOSEOUT_JOURNAL="$journal"
    export PIN_FIXTURE_ROOT="$pin_root"
    export PIN_FIXTURE_BUNDLE="$pin_bundle"
    export PIN_FIXTURE_MAKE_LOG="$pin_make_log"
    export PATH="$fake_make_dir:$PATH"
    run_release_checklist --prepare-status-doc-closeout "$token"
  ) >"$output" 2>&1
  [[ "$(wc -l < "$pin_make_log" | tr -d '[:space:]')" == "15" ]]
  [[ "$(rg -c ' candidate$' "$pin_make_log")" == "6" ]]
  [[ "$(rg -c ' isolated$' "$pin_make_log")" == "2" ]]
  [[ "$(rg -c ' ordinary$' "$pin_make_log")" == "7" ]]
  rg -Fxq 'lint candidate' "$pin_make_log"
  rg -Fxq 'test-local-isolated isolated' "$pin_make_log"
  rg -Fxq 'simulate-full ordinary' "$pin_make_log"
  [[ -s "$destination/tmp/release-closeout/testnet.pending.json" ]]
  jq -e '
    .schema == "soraswap-release-closeout/v2"
    and .status == "pending_status_docs"
    and .environment == "testnet"
    and (.source.git_head | type == "string" and length == 40)
    and (.source.tracked_non_status_doc_sha256 | test("^[0-9a-f]{64}$"))
    and (.evidence.release_evidence_sha256 | test("^[0-9a-f]{64}$"))
    and (.evidence.chain_fingerprint.block_1_hash == "fixture-block")
    and (.evidence.final_generated_at["deployments/testnet/contracts.latest.json"] == "20260622T000570Z")
    and (.phase_journal.phases | length == 11)
    and (.resume_token | test("^[0-9a-f]{64}$"))
    and (.checkpoint_sha256 | test("^[0-9a-f]{64}$"))
  ' "$destination/tmp/release-closeout/testnet.pending.json" >/dev/null
  [[ "$(stat -f '%Lp' "$destination/tmp/release-closeout/testnet.pending.json")" == "600" ]]
  [[ ! -e "$journal" ]]
  rg -q "release remains pending status-doc closeout" "$output"
  ! rg -q "release checklist ok" "$output"
}

run_closeout_resume() {
  local destination="$1"
  local checkpoint="$destination/tmp/release-closeout/testnet.pending.json"
  local token

  token="$(release_closeout_checkpoint_resume_token "$destination" testnet "$checkpoint")"
  export SORASWAP_ROOT="$destination"
  export SORASWAP_RELEASE_ENV=testnet
  export RELEASE_CHECKLIST_INTERNAL_CLOSEOUT_TOKEN="$token"
  unset RELEASE_CHECKLIST_INTERNAL_CLOSEOUT_JOURNAL
  run_release_checklist --resume-status-doc-closeout "$token"
}

