  eval "env_value=\${$env_name:-}"
  [ -z "$env_value" ] || fail "unsafe inherited env $env_name"
done

case "$target" in
  lint|compile|dev-check|dev-build|dev-test|dev-schema|test-local-foundation-isolated|test-local-isolated)
    [ "${SORASWAP_IROHA_ROOT:-}" = "$PIN_FIXTURE_ROOT" ] || fail "$target candidate root"
