import re
import sys
from pathlib import Path

script_path = Path(sys.argv[1])
checklist_path = Path(sys.argv[2])
script = script_path.read_text()
checklist = checklist_path.read_text()

match = re.search(r"local_acceptance_targets=\(\n(?P<body>.*?)\n\)", script, re.S)
if not match:
    raise SystemExit("release_checklist.sh has no local_acceptance_targets array")
script_targets = {
    line.strip()
    for line in match.group("body").splitlines()
    if line.strip() and not line.strip().startswith("#")
}

try:
    section = checklist.split("## Required Local Acceptance", 1)[1].split("\n\n", 1)[0]
except IndexError as exc:
    raise SystemExit("production readiness checklist has no Required Local Acceptance section") from exc
doc_targets = {
    line.strip()[len("- `make "):-1]
    for line in section.splitlines()
    if line.strip().startswith("- `make ") and line.strip().endswith("`")
}

missing = sorted(doc_targets - script_targets)
extra = sorted(script_targets - doc_targets)
if missing or extra:
    raise SystemExit(
        "release local acceptance target drift: "
        f"missing_in_script={missing} extra_in_script={extra}"
    )
PY
