  in_fn && /make -C "\$ROOT" "\$target"/ { make_call = NR }
  in_fn && /^\}/ { in_fn = 0 }
  END { exit !(chain_scrub > 0 && scrub > chain_scrub && make_call > scrub) }
' "$ROOT/scripts/release_production.sh"
python3 - "$ROOT/scripts/release_checklist.sh" "$ROOT/scripts/release_production.sh" <<'PY'
import re
import sys
from pathlib import Path


def function_body(path: Path, name: str) -> str:
    text = path.read_text()
    match = re.search(rf"^%s\(\) \{{(?P<body>.*?)^\}}" % re.escape(name), text, re.M | re.S)
    if not match:
        raise SystemExit(f"{path.name} has no {name} function")
    return match.group("body")


def scrub_vars(path: Path, name: str) -> set[str]:
    env_names: set[str] = set()
    for line in function_body(path, name).splitlines():
        stripped = line.strip()
        if not stripped.startswith("unset "):
            continue
        for token in stripped.split()[1:]:
            if re.fullmatch(r"SORASWAP_[A-Z0-9_]+|CHAIN|ACCOUNT_CHAIN_DISCRIMINANT|IROHA_ACCOUNT_CHAIN_DISCRIMINANT", token):
                env_names.add(token)
    return env_names


checklist = scrub_vars(Path(sys.argv[1]), "run_local_acceptance_target")
production = scrub_vars(Path(sys.argv[2]), "require_taira_release_gate")
production_sets_inline = {"SORASWAP_PUBLIC_ENV", "SORASWAP_RELEASE_ENV"}
missing = sorted(checklist - production_sets_inline - production)
if missing:
    raise SystemExit(
        "release-production Taira prerequisite scrub drift: "
        + ", ".join(missing)
    )
PY
python3 - "$ROOT" <<'PY'
import re
import sys
from pathlib import Path


root = Path(sys.argv[1])
script = (root / "scripts/release_checklist.sh").read_text()
match = re.search(
    r"^run_local_acceptance_target\(\) \{(?P<body>.*?)^\}",
    script,
    re.M | re.S,
)
if not match:
    raise SystemExit("release_checklist.sh has no run_local_acceptance_target function")

scrubbed = set()
for line in match.group("body").splitlines():
    stripped = line.strip()
    if not stripped.startswith("unset "):
        continue
    scrubbed.update(
        token
        for token in stripped.split()[1:]
        if re.fullmatch(r"SORASWAP_[A-Z0-9_]+|CHAIN|ACCOUNT_CHAIN_DISCRIMINANT|IROHA_ACCOUNT_CHAIN_DISCRIMINANT", token)
    )

source_paths = [
    root / "Makefile",
    root / "scripts/common.sh",
    root / "scripts/dev_iroha.sh",
    root / "scripts/compile_contracts.sh",
    root / "scripts/lint_contracts.sh",
    root / "scripts/release_checklist.sh",
    root / "scripts/release_production.sh",
    root / "scripts/release_production_checklist.sh",
    root / "scripts/release_taira.sh",
    root / "tests/isolated_e2e.sh",
    root / "tests/isolated_foundation_e2e.sh",
    root / "scripts/deploy_local.sh",
    root / "scripts/smoke_local.sh",
    root / "scripts/bootstrap_assets.sh",
    root / "scripts/bootstrap_contract_state.sh",
    root / "scripts/deploy_public.sh",
    root / "scripts/smoke_public.sh",
    root / "scripts/smoke_public_mutating.sh",
    root / "scripts/taira_preflight.sh",
    root / "scripts/contract_console_public_smoke.sh",
    root / "scripts/trader_public.sh",
    root / "scripts/publish_trader_api_bundle.sh",
    root / "scripts/record_rwa_compliance.sh",
    root / "scripts/taira_state_repair_plan.sh",
]
high_risk_patterns = [
    r"^CHAIN$",
    r"^(ACCOUNT_CHAIN_DISCRIMINANT|IROHA_ACCOUNT_CHAIN_DISCRIMINANT)$",
    r"^SORASWAP_(CLIENT_CONFIG|PRODUCTION_CLIENT_CONFIG|CONTRACTS_MANIFEST|PROFILE)$",
    r"^SORASWAP_ALLOW_(TESTNET|PRODUCTION)_MUTATIONS$",
    r"^SORASWAP_RELEASE_ENV$",
    r"^SORASWAP_RELEASE_CHECKLIST_",
    r"^SORASWAP_(PUBLIC|TESTNET|PRODUCTION|TAIRA)_",
    r"^SORASWAP_CHAIN_",
    r"^SORASWAP_TORII_",
    r"^SORASWAP_(IROHA|KOTO|SORAFS)_",
    r"^SORASWAP_ISOLATED_",
    r"^SORASWAP_ACTIVE_(IROHA|SPLIT|GOV|SORAFS)_",
    r"^SORASWAP_SKIP_(IROHA|KOTO|LOCALNET).*TOOL_BUILD$",
    r"^SORASWAP_FORCE_COMPILE$",
    r"^SORASWAP_PREFLIGHT_",
    r"^SORASWAP_INIT_CONTRACT_STATE$",
    r"^SORASWAP_RUN_(TESTNET_SMOKE|CONTRACT_CONSOLE_LIVE_SMOKE)$",
    r"^SORASWAP_ASSERT_BOOTSTRAP_STATE$",
    r"^SORASWAP_(BOOTSTRAP_SCOPE|DEPLOY_SCOPE|SMOKE_SCOPE)$",
    r"^SORASWAP_EXPECTED_TRIGGER_SCOPE$",
    r"^SORASWAP_(TRIGGER_LIFECYCLE|PERPS_TRIGGER_LIFECYCLE|DLMM_RANGE_GOVERNOR|TWAMM_TRIGGER)_",
    r"^SORASWAP_REQUIRE_STANDALONE_BRIDGE_PROOF$",
    r"^SORASWAP_(ORACLE_PUBLIC_KEY_HEX|ORACLE_PRIVATE_KEY_HEX|ORACLE_PYTHON_BIN|ORACLE_SCHEME)$",
    r"^SORASWAP_LAST_ORACLE_SLOT$",
    r"^SORASWAP_ENABLE_RWA_RELEASE$",
    r"^SORASWAP_RWA_COMPLIANCE_",
    r"^SORASWAP_RWA_(ISSUER|LEGAL|NAV|REDEMPTION)_",
    r"^SORASWAP_TRADER_(API|PUBLIC)_",
    r"^SORASWAP_PUBLISH_TRADER_API_BINDING$",
]
high_risk = [re.compile(pattern) for pattern in high_risk_patterns]
allowed_unscrubbed = {
    "SORASWAP_TESTNET_CHAIN_DISCRIMINANT_DEFAULT",
    "SORASWAP_TESTNET_CHAIN_ID_DEFAULT",
}

referenced = {}
for path in source_paths:
    text = path.read_text()
    for name in re.findall(r"\b(?:SORASWAP_[A-Z0-9_]+|CHAIN|ACCOUNT_CHAIN_DISCRIMINANT|IROHA_ACCOUNT_CHAIN_DISCRIMINANT)\b", text):
        if any(pattern.search(name) for pattern in high_risk):
            referenced.setdefault(name, set()).add(path.relative_to(root).as_posix())

missing = sorted(set(referenced) - allowed_unscrubbed - scrubbed)
if missing:
    details = ", ".join(
        f"{name} ({', '.join(sorted(referenced[name]))})"
        for name in missing
    )
    raise SystemExit("release local acceptance scrub is missing high-risk env vars: " + details)
