    and (.operator_inputs.reason | contains("[local-path]/repair.log"))
    and (.operator_inputs.snapshot_policy | contains("fixture snapshot policy"))
    and (.operator_inputs.snapshot_policy | contains("[redacted]"))
    and (.operator_inputs.operator | contains("fixture-operator"))
    and (.operator_inputs.operator | contains("[redacted]"))
