assert_requires_production_mutation_gate() {
  local label="$1"
  local script_path
  shift
  script_path="$1"
  shift
  local output="$TMP_DIR/production-mutation-gate-${label}.out"
  local cmd_status=0

  (
    export SORASWAP_PUBLIC_ENV=production
    export SORASWAP_ALLOW_TESTNET_MUTATIONS=1
    unset SORASWAP_ALLOW_PRODUCTION_MUTATIONS
    unset SORASWAP_CLIENT_CONFIG SORASWAP_PRODUCTION_CLIENT_CONFIG
    run_repo_zsh_script "$script_path" "$@"
  ) >"$output" 2>&1 || cmd_status="$?"
  [[ "$cmd_status" != "0" ]]
  rg -q "export SORASWAP_ALLOW_PRODUCTION_MUTATIONS=1 to continue" "$output"
  ! rg -q "export SORASWAP_ALLOW_TESTNET_MUTATIONS=1 to continue" "$output"
}

