contract_view_expect_stale_output="$TMP_DIR/contract-view-expect-stale.out"
(
  fixture_view_attempts_file="$TMP_DIR/contract-view-expect-attempts"
  printf '0\n' > "$fixture_view_attempts_file"
  submit_contract_view() {
    local fixture_view_attempts
    fixture_view_attempts="$(<"$fixture_view_attempts_file")"
    fixture_view_attempts=$(( fixture_view_attempts + 1 ))
    printf '%s\n' "$fixture_view_attempts" > "$fixture_view_attempts_file"
    if (( fixture_view_attempts < 3 )); then
      printf '%s\n' '{"ok":true,"result":["1","10","10","0","0"],"normalized_result":[1,10,10,0,0]}'
    else
      printf '%s\n' '{"ok":true,"result":["1","10","10","0","1"],"normalized_result":[1,10,10,0,1]}'
    fi
  }

  export SORASWAP_CONTRACT_VIEW_EXPECT_RETRY_COUNT=3
  export SORASWAP_CONTRACT_VIEW_EXPECT_RETRY_DELAY_SECS=0
  submit_contract_view_expect \
    "$TMP_DIR/missing-view-config.toml" \
    "tairac1fixture" \
    "mirror_allocation" \
    100 \
    '{"allocation":"fixture"}' \
    '.ok == true and (.result[4] // 0) == 1' \
    "fixture refunded allocation"
  printf 'attempts=%s\n' "$(<"$fixture_view_attempts_file")"
) >"$contract_view_expect_stale_output" 2>&1
rg -Fq '"normalized_result":[1,10,10,0,1]' "$contract_view_expect_stale_output"
rg -Fq "attempts=3" "$contract_view_expect_stale_output"

