assert_rejects_cross_env_public_config() {
  local label="$1"
  local expected="$2"
  shift 2
  local output="$TMP_DIR/cross-env-public-config-${label}.out"
  local cmd_status=0
  typeset -a command_args
  command_args=("$@")

  (
    export SORASWAP_ALLOW_TESTNET_MUTATIONS=1
    export SORASWAP_ALLOW_PRODUCTION_MUTATIONS=1
    if [[ "${command_args[1]:-}" == "env" ]]; then
      command_args=("${command_args[@]:1}")
      while (( ${#command_args[@]} > 0 )); do
        case "${command_args[1]}" in
          -u)
            unset "${command_args[2]}"
            command_args=("${command_args[@]:2}")
            ;;
          *=*)
            export "${command_args[1]}"
            command_args=("${command_args[@]:1}")
            ;;
          *)
            break
            ;;
        esac
      done
    fi
    if [[ "${command_args[1]:-}" == "run_repo_zsh_script" ]]; then
      command_args=("${command_args[@]:1}")
    fi
    run_repo_zsh_script "${command_args[@]}"
  ) >"$output" 2>&1 || cmd_status="$?"
  [[ "$cmd_status" != "0" ]]
  rg -q "$expected" "$output"
}

