assert_uses_production_client_config_default() {
  local label="$1"
  shift
  local missing_cfg="$TMP_DIR/production-client-default-${label}.toml"
  local output="$TMP_DIR/production-client-default-${label}.out"
  local cmd_status=0

  (
    export SORASWAP_PUBLIC_ENV=production
    export SORASWAP_ALLOW_PRODUCTION_MUTATIONS=1
    unset SORASWAP_ALLOW_TESTNET_MUTATIONS
    unset SORASWAP_CLIENT_CONFIG
    export SORASWAP_PRODUCTION_CLIENT_CONFIG="$missing_cfg"
    run_repo_zsh_script "$@"
  ) >"$output" 2>&1 || cmd_status="$?"
  [[ "$cmd_status" != "0" ]]
  rg -q "missing required file: $(basename "$missing_cfg")" "$output"
  ! rg -Fq "$TMP_DIR" "$output"
  ! rg -q "config/testnet/taira.client.toml" "$output"
}

