cat > "$TMP_DIR/taira_preflight_fixture.py" <<'PY'
#!/usr/bin/env python3
import json
import socketserver
import sys
from http.server import BaseHTTPRequestHandler


def status_from_file(path, default):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return int(handle.read().strip())
    except Exception:
        return default


def text_from_file(path, default):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return handle.read().strip()
    except Exception:
        return default


FAUCET_STATUS_PATH = sys.argv[2]
MCP_STATUS_PATH = sys.argv[3]
STATUS_MODE_PATH = sys.argv[4]


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/v1/explorer/blocks/1":
            if text_from_file(STATUS_MODE_PATH, "json") == "missing-block":
                self.send_response(503)
                self.end_headers()
                return
            self.send_response(200)
            self.send_header("content-type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps({
                "hash": "fixture-block-1",
                "height": 1,
            }).encode())
            return

        if self.path == "/status/blocks":
            self.send_response(200)
            self.send_header("content-type", "application/json")
            self.end_headers()
            self.wfile.write(b"42")
            return

        if self.path == "/status":
            if text_from_file(STATUS_MODE_PATH, "json") == "binary":
                self.send_response(200)
                self.send_header("content-type", "application/octet-stream")
                self.end_headers()
                self.wfile.write(b"NRT0\x00\x00fixture-non-json-status")
                return

            self.send_response(200)
            self.send_header("content-type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps({
                "blocks": 77,
                "peers": 3,
                "queue_size": 2,
                "queue_queued": 1,
                "queue_inflight": 1,
                "time_since_last_block_ms": 1000,
                "teu_dataspace_backlog": [
                    {"backlog": 0},
                    {"backlog": 4},
                ],
            }).encode())
            return

        if self.path == "/v1/sumeragi/status":
            self.send_response(200)
            self.send_header("content-type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps({
                "protocol_version": 4,
                "restart_required": False,
                "height_context_id": "fixture-height-78",
                "height": 78,
                "view": 2,
                "phase": {"phase": "prepare", "details": None},
                "leader": 0,
                "body_state": {"state": "validated", "details": None},
                "pending_persistence_id": None,
                "last_committed_height": 77,
                "last_committed_subject": "fixture-subject-77",
                "liveness": {"no_progress_age_ms": 1000, "blocker": None},
            }).encode())
            return

        if self.path == "/v1/sumeragi/diagnostics":
            self.send_response(200)
            self.send_header("content-type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps({
                "pipeline_execution": None,
                "tx_queue_depth": 1,
                "tx_queue_capacity": 4096,
                "tx_queue_retained_bytes": 128,
                "tx_queue_max_retained_bytes": 13631488,
                "tx_queue_saturated": False,
                "tx_queue_saturated_by_count": False,
                "tx_queue_saturated_by_bytes": False,
                "tx_queue_saturated_by_age": False,
                "tx_queue_oldest_queued_age_ms": 12,
            }).encode())
            return

        if self.path == "/v1/accounts/faucet/puzzle":
            self.send_response(status_from_file(FAUCET_STATUS_PATH, 200))
            self.send_header("content-type", "application/json")
            self.end_headers()
            self.wfile.write(b'{"algorithm":"fixture"}')
            return

        if self.path == "/v1/mcp":
            mcp_status = status_from_file(MCP_STATUS_PATH, 404)
            self.send_response(mcp_status)
            self.send_header("content-type", "application/json")
            self.end_headers()
            if mcp_status == 200:
                mode = text_from_file(STATUS_MODE_PATH, "json")
                enabled = mode != "mcp-disabled"
                tool_count = 0 if mode == "mcp-incomplete" else 12
                toolset_version = "" if mode == "mcp-incomplete" else "fixture-tools-v1"
                self.wfile.write(json.dumps({
                    "enabled": enabled,
                    "protocolVersion": "2025-06-18",
                    "serverInfo": {"name": "iroha-torii-mcp", "version": "0.0.0-dev"},
                    "capabilities": {
                        "tools": {
                            "listChanged": False,
                            "count": tool_count,
                            "toolsetVersion": toolset_version,
                        }
                    },
                }).encode())
            return

        self.send_response(404)
        self.end_headers()

    def log_message(self, *_args):
        pass


with socketserver.TCPServer(("127.0.0.1", 0), Handler) as httpd:
    port_path = sys.argv[1]
    with open(port_path, "w", encoding="utf-8") as handle:
        handle.write(str(httpd.server_address[1]))
    httpd.serve_forever()
PY

