[[ -s "$refresh_archive_dir/chain.latest.json" ]]
[[ -s "$refresh_archive_dir/preflight.latest.json" ]]
[[ ! -e "$refresh_chain_report_dir/preflight.latest.json" ]]
! rg -Fq "$TMP_DIR" "$refresh_chain_latest"

