    "torii_url": "$fixture_root",
    "chain": "$SORASWAP_TESTNET_CHAIN_ID_DEFAULT",
    "block_1_hash": "fixture-block-1"
  },
  "supported": false,
  "summary": "fixture nested-call deploy failed private_key=802620PREFLIGHTSECRET",
  "health_snapshot": {
    "sumeragi": {
      "http_status": "200",
      "summary": {
        "height": 78,
        "last_committed_height": 77,
        "phase": "prepare",
        "blocker": null
      }
    },
    "sumeragi_diagnostics": {
      "http_status": "200",
      "summary": {
        "tx_queue_depth": 1,
        "tx_queue_saturated": false,
        "tx_queue_saturated_by_age": false,
        "tx_queue_saturated_by_count": false,
