preflight_redaction_status=0
redaction_fixture_root="http://operator:supersecret@127.0.0.1:$(cat "$fixture_port_file")"
redaction_chain_config="$TMP_DIR/redaction-chain.client.toml"
cat > "$redaction_chain_config" <<EOF
chain = "$SORASWAP_TESTNET_CHAIN_ID_DEFAULT"
network_id = "hash:82531CE8EAE8BFF6BEECA4698BFD13A3BC8BEC5F0EE0D23D428C97FC17AB0F3B#3E94"
torii_url = "$redaction_fixture_root"
EOF
redacted_chain_fingerprint="$(
  export SORASWAP_TORII_READ_MAX_TIME_SECS=2
  export SORASWAP_CHAIN_FINGERPRINT_ATTEMPTS=1
  export SORASWAP_CHAIN_FINGERPRINT_SLEEP_SECS=0
  current_chain_fingerprint_json "$redaction_chain_config"
)"
jq -e \
  '(.torii_url | contains("http://[redacted]@127.0.0.1:"))
    and .block_1_hash == "fixture-block-1"' \
  <<<"$redacted_chain_fingerprint" >/dev/null
[[ "$redacted_chain_fingerprint" != *supersecret* ]]
(
  unset SORASWAP_PUBLIC_ENV
  export SORASWAP_TORII_URL="$redaction_fixture_root"
  export SORASWAP_ROOT="$preflight_root"
  export SORASWAP_CLIENT_CONFIG="$missing_cfg"
  export SORASWAP_TAIRA_PREFLIGHT_TIMEOUT_SECS=2
  export SORASWAP_TAIRA_PREFLIGHT_REPORT_DIR="$preflight_redaction_report_dir"
  run_repo_zsh_script "$ROOT/scripts/taira_preflight.sh"
) >"$preflight_redaction_output" 2>&1 || preflight_redaction_status="$?"
