rg -q "taira preflight: blocked" "$preflight_redaction_output"
rg -q "native Torii MCP is not enabled" "$preflight_redaction_output"
rg -q '\[redacted\]@127\.0\.0\.1' "$preflight_redaction_output"
! rg -q 'supersecret|operator:supersecret' "$preflight_redaction_output"

preflight_redaction_report="$preflight_redaction_report_dir/preflight.latest.json"
[[ -s "$preflight_redaction_report" ]]
jq -e \
  '.status == "blocked"
    and (.target_environment == "testnet")
    and (.endpoint.torii_root | contains("http://[redacted]@127.0.0.1:"))
    and (.chain.fingerprint.torii_url | contains("http://[redacted]@127.0.0.1:"))
    and (.blockers | any(contains("[redacted]@127.0.0.1")))' \
  "$preflight_redaction_report" >/dev/null
! rg -q 'supersecret|operator:supersecret' "$preflight_redaction_report"
! rg -Fq "$TMP_DIR" "$preflight_redaction_report"

preflight_output="$TMP_DIR/taira_preflight.out"
preflight_status=0
(
  unset SORASWAP_PUBLIC_ENV
  export SORASWAP_TORII_URL="$fixture_root"
  export SORASWAP_ROOT="$preflight_root"
  export SORASWAP_CLIENT_CONFIG="$missing_cfg"
  export SORASWAP_TAIRA_PREFLIGHT_TIMEOUT_SECS=2
