  run_repo_zsh_script "$ROOT/scripts/taira_preflight.sh"
) >"$preflight_output" 2>&1 || preflight_status="$?"
[[ "$preflight_status" != "0" ]]
rg -q "taira preflight: blocked" "$preflight_output"
rg -q "native Torii MCP is not enabled" "$preflight_output"
rg -q "saved chain.latest.json was recorded for environment" "$preflight_output"
rg -q "nested-call health:" "$preflight_output"
rg -q "latest nested-call probe for current Taira chain is unsupported: fixture nested-call deploy failed private_key=" "$preflight_output"
! rg -q "802620PREFLIGHTSECRET" "$preflight_output"
rg -q "next setup:" "$preflight_output"

preflight_report="$preflight_report_dir/preflight.latest.json"
[[ -s "$preflight_report" ]]
jq -e \
	  --arg fixture_root "$fixture_root" \
	  '.status == "blocked"
    and (.target_environment == "testnet")
    and (.endpoint.torii_root == $fixture_root)
    and (.endpoint.mcp_http_status == "404")
    and (.blockers | any(contains("native Torii MCP is not enabled")))
    and (.blockers | any(contains("saved chain.latest.json was recorded for environment \"production\", not \"testnet\"")))
    and (.endpoint.faucet_puzzle_http_status == "200")
    and (.endpoint.current_block_height == 42)
    and (.chain.fingerprint_available == true)
    and (.chain.fingerprint.block_1_hash == "fixture-block-1")
	    and (.chain.saved_snapshot_exists == true)
	    and (.chain.saved_snapshot_environment == "production")
	    and (.chain.saved_snapshot_matches == false)
	    and (.nested_call_probe.supported == false)
	    and (.nested_call_probe.summary | contains("fixture nested-call deploy failed private_key="))
	    and ((.nested_call_probe.summary | contains("802620PREFLIGHTSECRET")) | not)
	    and (.nested_call_probe.health_summary == "height=78 last_committed=77 queue_depth=1 saturated=false saturated_by_age=false blocker=none")
    and (.config.exists == false)
    and (.config.path == "missing-taira.client.toml")
    and (.artifacts["chain.latest.json"].path == "deployments/testnet/chain.latest.json")
    and (.artifacts["nested_call_probe.latest.json"].path == "deployments/testnet/nested_call_probe.latest.json")' \
	  "$preflight_report" >/dev/null
! rg -q "802620PREFLIGHTSECRET" "$preflight_report"
! rg -Fq "$TMP_DIR" "$preflight_report"

cat > "$preflight_report_dir/chain.latest.json" <<EOF
{
