! rg -q "rwa compliance evidence already current" "$rwa_missing_torii_reuse_output"
cp "$TMP_DIR/rwa-compliance-testnet-baseline.json" "$rwa_report"

rwa_stale_preflight_reuse_output="$TMP_DIR/rwa-compliance-stale-preflight-reuse.out"
rwa_stale_preflight_reuse_status=0
jq '.generated_at = "99991231T000000Z"' "$TMP_DIR/rwa-compliance-preflight-baseline.json" \
